-- Thread 1 (sort 302): the-son-of-the-living-elohim-named-before-the-foundation-in-1-enoch-and-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-son-of-the-living-elohim-named-before-the-foundation-in-1-enoch-and-wisdom-of-solomon',
       'The Son of the living Elohim named before the foundation — 1 Enoch 46 and 48, and Wisdom of Solomon 2 (FRAMEWORK-MAJOR)',
       'Matt 16:13-17''s Caesarea-Philippi-confession sequence — the King''s-credentialing-question *whom do men say that I the Son of Adam am?* (v.13), Kefa''s (Peter''s) *thou art the Messiah, the Son of the living Elohim (God)* (v.16), and the King''s-blessing *flesh and blood hath not revealed it unto thee, but my Father which is in heaven* (v.17) — read against the wisdom-stream''s direct articulation of the Son-of-Adam / Son-of-the-living-Elohim named-before-the-foundation substance. Five moves: 1 Enoch 46:2 names the wisdom-stream verbal-anchor for the Son-of-Adam title the King uses of himself (*concerning that Son of Adam, who he was, and whence he was, and why he went with the Head of Days*); 1 Enoch 46:3 names the depth of the Son-of-Adam''s identity (*this is the Son of Adam who hath righteousness, with whom dwelleth righteousness*); 1 Enoch 48:2 names the heavenly-naming-of-the-Christ at the throne (*that Son of Adam was named in the presence of Yahuah (God) of Spirits, and his name before the Head of Days*); 1 Enoch 48:3 names THE direct verbal-anchor for the before-the-foundation-of-the-world naming (*before the sun and the signs were created, before the stars of the heaven were made, his name was named before Yahuah (God) of Spirits*); Wisdom of Solomon 2:18 names the just-man-as-the-son-of-Yahuah substance in the prefiguring-passage (*if the just man be the son of Yahuah (God), he will help him*). The framework reads the cluster as FRAMEWORK-MAJOR for the cause-and-effect-of-hearing per Red Line #11 operating at the Caesarea-Philippi-confession. Kefa''s (Peter''s)-confession articulates at the earthly-gospel-pivot what the Parables-of-Enoch and the Wisdom-of-Solomon-prefiguring-passage had named at the heavenly-throne and wisdom-stream-prefiguring registers centuries before. The Father''s-revelation to Kefa (Peter) reveals what was always true — the Son-of-Adam''s name was named before the foundation of the world; the cause-and-effect-of-hearing operates at the Father''s revealing the same substance the wisdom-stream had carried.',
       sv.verse_id, ev.verse_id, 'complete_study', 302
  FROM _s146_verse_lookup sv, _s146_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 16 AND sv.verse_number = 13
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 16 AND ev.verse_number = 17
ON CONFLICT (slug) DO NOTHING;

-- Thread 2 (sort 303): the-elect-one-on-the-throne-and-the-davidic-stewardship-keys-in-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-elect-one-on-the-throne-and-the-davidic-stewardship-keys-in-1-enoch',
       'The Elect One on the throne and the Davidic stewardship keys — 1 Enoch 49, 51, 62, and 69 (FRAMEWORK-MAJOR)',
       'Matt 16:19''s *I will give unto thee the keys of the kingdom of heaven: and whatsoever thou shalt bind on earth shall be bound in heaven: and whatsoever thou shalt loose on earth shall be loosed in heaven* — read against the wisdom-stream''s direct articulation of the Elect-One on the throne and the sum-of-judgment-committed-unto-the-Son-of-Adam substance. Four moves: 1 Enoch 49:2 names the Elect-One-as-the-Standing-One-before-Yahuah-of-Spirits to whom the secrets-of-righteousness are committed (*he is mighty in all the secrets of righteousness ... because the Elect One stands before Yahuah (the Lord) of Spirits*); 1 Enoch 51:3 names THE direct verbal-anchor for the Elect-One-on-the-throne substance (*the Elect One shall in those days sit on My throne, and his mouth shall pour forth all the secrets of wisdom and counsel*); 1 Enoch 62:7 names the Son-of-Adam revealed-to-the-holy-and-elect substance (*the righteousness of the Elect One of Yahuah (God) of Spirits hath revealed him to the holy and elect*); 1 Enoch 69:27 names the sum-of-judgment-given-unto-the-Son-of-Adam substance (*he sat on the throne of his glory, and the sum of judgment was given unto the Son of Adam*). The framework reads the cluster as FRAMEWORK-MAJOR for the apostolic-stewardship''s derivation from the King''s-own-throne-position. The short.md walks the Yeshayahu (Isaiah) 22:15-25 Shevna-and-Elyakim succession as the Tanakh-architecture for the demotion-of-the-self-credentialing-Shevna-class (the contemporary Pharisaic-and-Sadducean second-Temple-aristocracy) and the elevation-of-the-Elyakim-class-of-apostolic-stewardship the King establishes at Kefa''s confession; the 1 Enoch Parables-cluster carries the upstream-architecture for the King''s-own-throne-position from which the keys are delegated. The King-as-the-Elect-One holds-the-throne and the sum-of-judgment; the King delegates the keys-of-the-kingdom-of-heaven to the apostolic-stewardship from that throne-position; the binding-and-loosing-substance the apostolic-stewardship exercises operates downstream-of-and-in-accountability-to the Son-of-Adam''s-own-sum-of-judgment. The inherited-Roman-Catholic-magisterial-authority-to-define-doctrine-against-scripture reading is ruled out — the apostolic-keys administer what-the-Master-of-the-House-has-given, not what-the-stewards-define-against-the-Master.',
       sv.verse_id, ev.verse_id, 'complete_study', 303
  FROM _s146_verse_lookup sv, _s146_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 16 AND sv.verse_number = 19
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 16 AND ev.verse_number = 19
ON CONFLICT (slug) DO NOTHING;

-- Thread 3 (sort 304): the-righteous-one-condemned-with-a-shameful-death-in-wisdom-of-solomon
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-righteous-one-condemned-with-a-shameful-death-in-wisdom-of-solomon',
       'The righteous one condemned with a shameful death — Wisdom of Solomon 2, 3, and 5',
       'Matt 16:21''s first-explicit-passion-prediction — *he must go unto Yerushalayim (Jerusalem), and suffer many things of the elders and chief priests and scribes, and be killed, and be raised again the third day* — read against the wisdom-stream''s direct articulation of the righteous-one persecuted-and-condemned-with-a-shameful-death and vindicated-in-the-resurrection substance. Five moves: Wisdom of Solomon 2:12 names the wicked''s-plot-against-the-righteous-one (*let us lie in wait for the righteous; because he is not for our turn, and he is clean contrary to our doings*); Wisdom of Solomon 2:16 names the wicked''s-grievance against the righteous-one''s-credentialing (*we are esteemed of him as counterfeits ... he maketh his boast that Yahuah (God) is his father*); Wisdom of Solomon 2:20 names THE direct verbal-anchor for the shameful-death (*let us condemn him with a shameful death*); Wisdom of Solomon 3:1 names the souls-of-the-righteous-preserved-in-the-Father''s-hand substance (*the souls of the righteous are in the hand of Yahuah (God), and there shall no torment touch them*); Wisdom of Solomon 5:1 names the righteous-man''s-vindication-before-the-face-of-the-wicked substance (*then shall the righteous man stand in great boldness before the face of such as have afflicted him*). The framework reads the cluster as the wisdom-stream''s direct prefiguring of the operative-substance the King''s-first-passion-prediction at Matt 16:21 names: the elders-and-chief-priests-and-scribes (the Pharisaic-and-Sadducean-second-Temple-aristocracy) are the wicked-Wisdom-of-Solomon-2 names; the King is the righteous-one-Wisdom-of-Solomon-2-prefigures; the suffering-and-killing the King names is the operative-fulfillment of the shameful-death the wisdom-stream had named; the third-day-raising is the operative-fulfillment of the vindication-of-the-righteous the wisdom-stream had named at Wisdom of Solomon 3:1 and 5:1. The framework reads the substance in continuity with the Tanakh-suffering-servant of Yeshayahu (Isaiah) 53 + the Devarim (Deuteronomy) 21:23 *cursed is every one that hangeth on a tree* the apostolic-stream-articulation at Galatians 3:13 lands; the wisdom-stream-prefiguring at Wisdom of Solomon 2-5 + the Tanakh-suffering-servant + the gospel-passion-prediction + the apostolic-stream-articulation cohere at the shameful-death-and-vindication architecture the King''s-own-passion-prediction names at v.21.',
       sv.verse_id, ev.verse_id, 'complete_study', 304
  FROM _s146_verse_lookup sv, _s146_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 16 AND sv.verse_number = 21
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 16 AND ev.verse_number = 21
ON CONFLICT (slug) DO NOTHING;

-- Thread 4 (sort 305): the-gates-of-sheol-and-the-resurrection-substance-in-wisdom-of-solomon-and-1-enoch
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'the-gates-of-sheol-and-the-resurrection-substance-in-wisdom-of-solomon-and-1-enoch',
       'The gates of Sheol and the resurrection substance — Wisdom of Solomon 1 and 16, 1 Enoch 51, and 2 Esdras 4',
       'Matt 16:18''s *the gates of hell shall not prevail against it* — the King''s-promise to the assembly-built-on-the-Rock that the gates-of-Sheol/Hades will not have-final-authority — read against the wisdom-stream''s direct articulation of the gates-of-Sheol and the resurrection-substance. Four moves: Wisdom of Solomon 1:13 names the death-is-not-from-Yahuah substance (*Yahuah (God) made not death: neither has he pleasure in the destruction of the living*); Wisdom of Solomon 16:13 names THE direct verbal-anchor for the gates-of-hell-and-the-bringing-up-again substance (*you have power of life and death: you leadest to the gates of hell, and bringest up again*); 1 Enoch 51:1 names the Sheol-giving-back-the-dead substance (*Sheol also shall give back that which it has received, and hell shall give back that which it owes*); 2 Esdras (4 Ezra) 4:35 names the souls-of-the-righteous-in-their-chambers substance (*did not the souls also of the righteous ask question of these things in their chambers, saying, How long shall I hope on this fashion?*). The framework reads the cluster as the wisdom-stream''s direct corroboration of the gates-of-Sheol/Hades-substance the King''s-promise enacts. The gates-of-Sheol carry the power-of-death-and-the-grave that entered through the curse-of-Bereshit (Genesis)-3 (Wisdom of Solomon 1:13''s articulation that the Father is-not-the-source-of-death); the Father''s-power leads-to-the-gates-and-brings-up-again (Wisdom of Solomon 16:13); the eschatological-architecture has Sheol-giving-back-the-dead and the chambers-delivering-the-souls (1 Enoch 51:1 + 2 Esdras 4:35); the King''s-resurrection at the sign-of-Yonah is the operative-substance that breaks the gates'' hold-against the assembly-built-on-him; the assembly partakes-of-the-resurrection-substance through-the-King at the first-resurrection per Revelation 20:4-6. The framework reads against the inherited-Christian-eternal-conscious-torment-hell reading of *gates of hell* — the Tanakh-substance and the wisdom-stream-substance carry the gates as the power-of-death-and-the-grave, not as the door to an eternal-conscious-torment institutional-Christian-doctrine.',
       sv.verse_id, ev.verse_id, 'complete_study', 305
  FROM _s146_verse_lookup sv, _s146_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 16 AND sv.verse_number = 18
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 16 AND ev.verse_number = 18
ON CONFLICT (slug) DO NOTHING;

-- Thread 5 (sort 306): reward-according-to-works-the-post-harvest-sifting-in-sirach-and-2-esdras
INSERT INTO cross_reference_threads (slug, title, summary_md, anchor_verse_id_start, anchor_verse_id_end, tier_required, sort_order)
SELECT 'reward-according-to-works-the-post-harvest-sifting-in-sirach-and-2-esdras',
       'Reward according to works — the post-harvest sifting — Sirach (Ecclesiasticus) 16 and 35, and 2 Esdras 7',
       'Matt 16:27''s *the Son of Adam shall come in the glory of his Father with his angels; and then he shall reward every man according to his works* — read against the wisdom-stream''s direct articulation of the rewarding-according-to-works at the day-of-judgment substance. Five moves: Sirach (Ecclesiasticus) 16:12 names the wisdom-stream''s headline-articulation (*as his mercy is great, so is his correction also: he judges a man according to his works*); Sirach 16:14 names the universal-substance (*every man shall find according to his works*); Sirach 35:19 names the rendering-to-every-man-according-to-his-deeds paired with the judging-of-the-cause-of-the-Father''s-people (*till he have rendered to every man according to his deeds ... till he have judged the cause of his people*); 2 Esdras (4 Ezra) 7:32 names the resurrection-of-the-dead-preceding-the-day-of-judgment substance (*the earth shall restore those that are asleep in her, and so shall the dust those that dwell in silence*); 2 Esdras 7:35 names THE direct verbal-anchor for the work-shall-follow-and-the-reward-shall-be-shewed substance (*the work shall follow, and the reward shall be shewed, and the good deeds shall be of force, and wicked deeds shall bear no rule*). The framework reads the cluster as the wisdom-stream''s direct corroboration of the post-harvest-sifting per Red Line #11 the King''s-Son-of-Adam-coming-and-rewarding substance at v.27 articulates at the gospel-pivot. The wisdom-stream had named the architecture of the rewarding-according-to-works at the day-of-judgment; the King names the operative-form at the Son-of-Adam''s-coming; the framework reads the substance in continuity with the framework''s-grace-and-the-opportunity-that-can-be-lost architecture — the grace is the door-home; the works are the fruit-of-the-new-heart-that-internalized-or-did-not-internalize per the Yechezk''el (Ezekiel) 36:26-27 substance; the reward at the day-of-judgment operates according-to-the-fruit, in the post-harvest-sifting Matt 7:21-23 + Matt 13:36-43 + Matt 25:31-46 articulate at the gospel-substance the wisdom-stream had named. The Tehillim (Psalm) 62:12 *thou renderest to every man according to his work* substance Romans 2:6 cites carries the same architecture across the canon and into the apostolic-stream.',
       sv.verse_id, ev.verse_id, 'complete_study', 306
  FROM _s146_verse_lookup sv, _s146_verse_lookup ev
 WHERE sv.edition_slug = 'canon' AND sv.book_slug = 'matthew' AND sv.chapter_number = 16 AND sv.verse_number = 27
   AND ev.edition_slug = 'canon' AND ev.book_slug = 'matthew' AND ev.chapter_number = 16 AND ev.verse_number = 27
ON CONFLICT (slug) DO NOTHING;

