-- Thread 1: the-son-of-the-living-elohim-named-before-the-foundation-in-1-enoch-and-wisdom-of-solomon
INSERT INTO cross_reference_thread_members (thread_id, cross_reference_id, sort_order, member_note)
SELECT t.id, x.id, 1, '1 Enoch 46:2 — *concerning that Son of Adam, who he was, and whence he was, and why he went with the Head of Days.* THE wisdom-stream verbal-anchor for the Son-of-Adam title the King uses of himself at Matt 16:13; the Parables-of-Enoch had carried the Son-of-Adam title as a heavenly-figure-named-beside-the-Head-of-Days centuries before the King''s-incarnation.'
